# owner: platform
import unittest

from rosterkit.notices import build_notice
from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError
from datetime import date

PUPIL = Student("7", "Rivera", "Ana", "A")


def mark(number, status="absent", owner="7"):
    return Mark(owner, date(2026, 9, number), status)


class NoticeTests(unittest.TestCase):
    def test_lists_dates_in_order(self):
        text = build_notice(PUPIL, [mark(9), mark(3), mark(5, "present")])
        self.assertEqual(text, "Ana Rivera missed 2 days of school: 2026-09-03, 2026-09-09.")

    def test_single_day(self):
        text = build_notice(PUPIL, [mark(4)])
        self.assertIn("missed 1 day of", text)

    def test_excused_not_counted(self):
        with self.assertRaises(ProjectError):
            build_notice(PUPIL, [mark(4, "excused")])

    def test_no_absences(self):
        with self.assertRaises(ProjectError):
            build_notice(PUPIL, [mark(4, "present")])
        with self.assertRaises(ProjectError):
            build_notice(PUPIL, [])

    def test_other_student(self):
        with self.assertRaises(ProjectError):
            build_notice(PUPIL, [mark(4), mark(5, owner="8")])


if __name__ == "__main__":
    unittest.main()
